function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 2000) return 'word needs 1 to 2000 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase English letters.';
  return null;
}

