function countDivisibleSubstrings(word) {
  const groups = ['ab', 'cde', 'fgh', 'ijk', 'lmn', 'opq', 'rst', 'uvw', 'xyz'];
  const value = new Map();
  for (let g = 0; g < groups.length; g++) {
    for (const letter of groups[g]) {
      value.set(letter, g + 1);
    }
  }
  let count = 0;
  for (let average = 1; average <= 9; average++) {
    const seen = new Map([[0, 1]]);
    let prefix = 0;
    for (const letter of word) {
      prefix += value.get(letter) - average;
      const matches = seen.get(prefix) ?? 0;
      count += matches;
      seen.set(prefix, matches + 1);
    }
  }
  return count;
}

