function countDivisibleSubstrings(word) {
  const digit = (ch) => {
    const code = ch.charCodeAt(0) - 97;
    return code < 2 ? 1 : 2 + Math.floor((code - 2) / 3);
  };
  let total = 0;
  for (let i = 0; i < word.length; i++) {
    let sum = 0;
    for (let j = i; j < word.length; j++) {
      sum += digit(word[j]);
      if (sum % (j - i + 1) === 0) total++;
    }
  }
  return total;
}

