function generate(rand, size) {
  const all = 'abcdefghijklmnopqrstuvwxyz';
  const pools = [all, 'abz', 'ab', 'cdefgh', 'xyz', 'aiq'];
  const pool = pools[Math.floor(rand() * pools.length)];
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 14);
  let word = '';
  for (let i = 0; i < n; i++) word += pool[Math.floor(rand() * pool.length)];
  return [word];
}
